// Copy of the router "Resolve + State Guard" logic (ALLOWED table, stale APPLYING, edit-session restore/abandon) and the Contact Route Guard. Keep in sync with the router.
const ALLOWED = {
  a: ["SENT", "APPLY_FAILED"],
  e: ["SENT", "AWAITING_CONFIRM", "DECLINED", "APPLIED", "UNDONE", "APPLY_FAILED"],
  d: ["SENT"],
  c: ["AWAITING_CONFIRM"],
  x: ["EDITING", "AWAITING_CONFIRM"],
  qc: ["SENT", "EDITING"],
  qr: ["SENT", "EDITING", "DECLINED", "UNDONE"],
  u: ["APPLIED", "APPLY_FAILED"],
  p: ["APPLIED", "UNDONE"],
  n: ["DECLINED", "APPLIED", "UNDONE"],
  PARSE: ["EDITING", "AWAITING_CONFIRM"],
};
const EDIT_STATES = ["EDITING", "AWAITING_CONFIRM"];
const STALE_APPLYING_MIN = 10;
function stateGuard(inp) {
  const route = inp.action;
  const sessActive = inp.session_active === true;
  const fromStatus = (inp.from_status && !EDIT_STATES.includes(inp.from_status)) ? inp.from_status : "SENT";
  let eff = inp.status;
  // APPLYING older than 10 min (or without updated_at) means the Apply run died: treat as APPLY_FAILED.
  if (eff === "APPLYING" && (inp.applying_age_min === undefined || inp.applying_age_min > STALE_APPLYING_MIN)) eff = "APPLY_FAILED";
  // Edit state without an active session: restore the pre-edit status.
  if (EDIT_STATES.includes(inp.status) && !sessActive) eff = fromStatus;
  if (!ALLOWED[route]) return true;
  let allowed = ALLOWED[route].includes(eff);
  // u / p / n during an open edit: allowed when the pre-edit status allows it (the edit is abandoned).
  if (!allowed && sessActive && ["u", "p", "n"].includes(route) && ALLOWED[route].includes(fromStatus)) allowed = true;
  return allowed;
}
function routeGuard(b) {
  let route = String(b.route || "").toUpperCase();
  if (b.opted_out === true) return "SKIP";
  if (!b.telegram_chat_id) return "SKIP";
  if (!["SKIP", "STAFF", "AUTO_APPLY", "SUGGEST", "ASK"].includes(route)) return "SKIP";
  return route;
}
const inp = $json.input;
if (inp.kind === "STATE") return { json: { allowed: stateGuard(inp) } };
return { json: { route: routeGuard(inp.bundle) } };

const tc = $('Test cases').item.json;
const actual = $json;
const exp = tc.expected;
const norm = arr => JSON.stringify((arr || []).map(c => ({ date: c.date, hours: c.hours })).sort((a, b) => a.date.localeCompare(b.date)));
const problems = [];
if (tc.target === "PARSE") {
  if (actual.intent !== exp.intent) problems.push("intent " + actual.intent + " != " + exp.intent);
  if (exp.changes && norm(actual.changes) !== norm(exp.changes)) problems.push("changes " + norm(actual.changes) + " != " + norm(exp.changes));
  if (exp.reason && actual.reason !== exp.reason) problems.push("reason " + actual.reason + " != " + exp.reason);
  if (exp.intent === "UNCLEAR" && Array.isArray(actual.changes) && actual.changes.length) problems.push("UNCLEAR must have no changes");
} else {
  if ("allowed" in exp && actual.allowed !== exp.allowed) problems.push("allowed " + actual.allowed + " != " + exp.allowed);
  if ("route" in exp && actual.route !== exp.route) problems.push("route " + actual.route + " != " + exp.route);
}
return { json: { name: tc.name, target: tc.target, input: tc.input.text || tc.input.action || "route guard", passed: problems.length === 0, details: problems.length ? problems.join("; ") : "ok", parser: actual.parser || null, actual } };

const cases = $input.all().map(i => i.json);
const passed = cases.filter(c => c.passed).length;
const total = cases.length;
return [{ json: {
  total,
  passed,
  failed: total - passed,
  pass_rate: total ? Math.round((passed / total) * 1000) / 10 + "%" : "0%",
  failed_cases: cases.filter(c => !c.passed).map(c => c.name + ": " + c.details),
  cases: cases.map(c => ({ name: c.name, target: c.target, passed: c.passed, parser: c.parser, details: c.details })),
} }];
